/**
 * Provision the development-only project-control policy of THIS checkout.
 * Provisions `.dev/orange-test-control-policy.json` in THIS development checkout
 * (the local development authority). It is never generated automatically.
 *
 * Why this cannot be generated by a test (read before changing):
 *   `packages/orangefilm/studio/server/isolation-control-policy.mjs` treats the file as
 *   *locally provisioned development authority*: it must be a plain file (not a link),
 *   single-link, realpath-identical, and its `baseRoot` must equal the isolation base
 *   root the running processes actually use. Its own header states the rule this tool
 *   exists to respect: "environment is not authority". If a test (or the app itself)
 *   wrote this file, any test could mint the authority it is then checked against, and
 *   the check would stop proving anything. So provisioning is an explicit operator
 *   action, taken once per checkout, by a human who knows which root is approved.
 *
 * Scope:
 *   - development checkouts only; never shipped, never run by the app, never part of
 *     install/update, never used in production;
 *   - one file per checkout (the path is derived from this script's location, exactly
 *     as `isolation-control-policy.mjs` derives it), not per user or per machine;
 *   - no defaults, no guessing: `--base-root` or `ORANGE_ISOLATION_ROOT` is required.
 *
 * Usage:
 *   node scripts/dev-provision-control-policy.mjs --base-root <absolute dir>
 *   ORANGE_ISOLATION_ROOT=<absolute dir> node scripts/dev-provision-control-policy.mjs
 *   node scripts/dev-provision-control-policy.mjs --check [--base-root <absolute dir>]
 *
 * Exit codes:
 *   0  provisioned / already provisioned / check passed
 *   1  (--check only) the policy file is missing, malformed, or names a different root
 *   2  argument error: no explicit root, two conflicting roots, or an unusable root
 *   3  conflict: a different policy already exists here (nothing was written)
 *   4  the write or the post-write self-check failed
 */
import { lstatSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { resolveIsolationProfile } from '../packages/orangefilm/src/development-isolation.mjs';

/** This checkout's own control-policy path; same derivation as isolation-control-policy.mjs. */
const checkoutRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const policyPath = join(checkoutRoot, '.dev', 'orange-test-control-policy.json');
const fold = value => (process.platform === 'win32' ? value.toLowerCase() : value);

const USAGE = `Usage:
  node scripts/dev-provision-control-policy.mjs --base-root <absolute dir>
  ORANGE_ISOLATION_ROOT=<absolute dir> node scripts/dev-provision-control-policy.mjs
  node scripts/dev-provision-control-policy.mjs --check [--base-root <absolute dir>]

Writes ${policyPath}
with {"version":1,"baseRoot":"<absolute dir>"}. The root must be an absolute,
local, non-C: development directory without alias segments (the same rule as
development-isolation.mjs rootPath()). There is no default root.
Exit codes: 0 ok, 1 check failed, 2 argument error, 3 existing different policy, 4 write/self-check failed.`;

/** @param {string} message @returns {never} */
function fail(code, message) {
  console.error(message);
  process.exit(code);
}

const args = process.argv.slice(2);
let flagRoot = null;
let checkOnly = false;
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  if (arg === '--help' || arg === '-h') { console.log(USAGE); process.exit(0); }
  else if (arg === '--check') checkOnly = true;
  else if (arg === '--base-root') {
    if (i + 1 >= args.length || args[i + 1].startsWith('--')) fail(2, '--base-root requires a value');
    flagRoot = args[++i];
  } else fail(2, `unknown argument: ${arg}\n\n${USAGE}`);
}
const envRoot = process.env.ORANGE_ISOLATION_ROOT ?? null;
if (flagRoot !== null && envRoot !== null && flagRoot !== '' && fold(resolve(flagRoot)) !== fold(resolve(envRoot))) {
  fail(2, `--base-root and ORANGE_ISOLATION_ROOT disagree:\n  --base-root            ${flagRoot}\n  ORANGE_ISOLATION_ROOT ${envRoot}\nNothing was written.`);
}
const requestedRoot = (flagRoot ?? envRoot) || null;
if (requestedRoot === null && !checkOnly) {
  fail(2, `an explicit approved base root is required; this tool has no default.\n\n${USAGE}`);
}

// Validate the root with the product's own rule, not a copy of it.
// `--check` without a root still works: it then only verifies the stored file.
/** @type {string | null} */
let canonicalRoot = null;
if (requestedRoot !== null) {
  try {
    canonicalRoot = resolveIsolationProfile(
      { baseRoot: requestedRoot, instanceId: 'provision', taskId: 'PROVISION', attemptId: 'provision-1', ports: { studio: 19841, film: 19842 } },
      { approvedBaseRoot: requestedRoot },
    ).baseRoot;
  } catch (error) {
    fail(2, `unusable base root: ${error instanceof Error ? error.message : String(error)}\nGiven: ${requestedRoot}`);
  }
  if (canonicalRoot !== requestedRoot) console.log(`note: using the normalised root ${canonicalRoot}`);
}

/** @returns {import('node:fs').Stats | null} */
function statOrNull(file) {
  try { return lstatSync(file); } catch (error) { if (error?.code === 'ENOENT') return null; throw error; }
}

/** Read, parse and validate an existing policy file; throws with a readable reason. */
function readPolicy() {
  const info = statOrNull(policyPath);
  if (!info) return null;
  if (info.isSymbolicLink()) throw new Error(`${policyPath} is a link, not a provisioned file`);
  if (!info.isFile()) throw new Error(`${policyPath} is not a regular file`);
  const raw = readFileSync(policyPath, 'utf8');
  let value;
  try { value = JSON.parse(raw); } catch { throw new Error(`${policyPath} is not valid JSON`); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`${policyPath} is not a JSON object`);
  const keys = Object.keys(value).sort().join(',');
  if (keys !== 'baseRoot,version') throw new Error(`${policyPath} must have exactly {version, baseRoot}; found {${keys}}`);
  if (value.version !== 1) throw new Error(`${policyPath} has version ${JSON.stringify(value.version)}, expected 1`);
  if (typeof value.baseRoot !== 'string' || value.baseRoot !== resolve(value.baseRoot)) {
    throw new Error(`${policyPath} baseRoot must be an absolute, normalised path; found ${JSON.stringify(value.baseRoot)}`);
  }
  // The stored root must itself still satisfy the isolation rules.
  resolveIsolationProfile(
    { baseRoot: value.baseRoot, instanceId: 'provision', taskId: 'PROVISION', attemptId: 'provision-1', ports: { studio: 19841, film: 19842 } },
    { approvedBaseRoot: value.baseRoot },
  );
  return { value, raw, info };
}

function selfCheck() {
  const info = statOrNull(policyPath);
  if (!info) return `self-check: ${policyPath} is missing after the write`;
  if (info.isSymbolicLink() || !info.isFile()) return `self-check: ${policyPath} is not a plain file`;
  if (info.nlink !== 1) return `self-check: ${policyPath} has nlink ${info.nlink}, expected 1`;
  let real;
  try { real = realpathSync(policyPath); } catch (error) { return `self-check: realpath failed: ${error.message}`; }
  if (fold(real) !== fold(policyPath)) return `self-check: ${policyPath} resolves to ${real}`;
  return null;
}

if (checkOnly) {
  let existing;
  try { existing = readPolicy(); }
  catch (error) { fail(1, `check failed: ${error.message}`); }
  if (!existing) fail(1, `check failed: no policy file at ${policyPath}; provision it with --base-root <absolute dir>`);
  const stored = existing.value.baseRoot;
  if (canonicalRoot !== null && fold(stored) !== fold(canonicalRoot)) {
    fail(1, `check failed: ${policyPath}\n  baseRoot        ${stored}\n  wanted          ${canonicalRoot}`);
  }
  const problem = selfCheck();
  if (problem) fail(1, `check failed: ${problem}`);
  console.log(`check ok\n  policy    ${policyPath}\n  baseRoot  ${stored}${canonicalRoot === null ? '' : '\n  matches   the root given'}`);
  process.exit(0);
}

let existing = null;
try { existing = readPolicy(); }
catch (error) { fail(3, `refusing to overwrite: ${error.message}\nNothing was written.`); }

const wanted = JSON.stringify({ version: 1, baseRoot: canonicalRoot });

if (existing) {
  const stored = existing.value.baseRoot;
  if (fold(stored) !== fold(canonicalRoot)) {
    fail(3, `refusing to overwrite an existing policy for a different root:\n  file    ${policyPath}\n  has     ${stored}\n  wanted  ${canonicalRoot}\nNothing was written; remove the file yourself if it is genuinely stale.`);
  }
  const problem = selfCheck();
  if (problem) fail(4, problem);
  console.log(`already provisioned (left untouched${existing.raw === wanted ? '' : ', formatting differs'})\n  policy    ${policyPath}\n  baseRoot  ${stored}`);
  process.exit(0);
}

try {
  mkdirSync(dirname(policyPath), { recursive: true });
  writeFileSync(policyPath, wanted, { flag: 'wx', mode: 0o600 });
} catch (error) {
  if (error?.code === 'EEXIST') fail(3, `a policy appeared while provisioning ${policyPath}; nothing was changed. Re-run --check.`);
  fail(4, `write failed: ${error?.message ?? error}`);
}
const problem = selfCheck();
if (problem) fail(4, problem);
console.log(`provisioned\n  policy    ${policyPath}\n  baseRoot  ${canonicalRoot}\n  checkout  ${checkoutRoot}`);
process.exit(0);
